import{A as r}from"./layout-Dd2zZ829.js";const e=document.getElementById("apply-form"),t=document.getElementById("msg");e.addEventListener("submit",async n=>{n.preventDefault(),t.className="msg",t.textContent="전송 중...";try{const a=await(await fetch(`${r}/api/applications`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:e.name.value.trim(),phone:e.phone.value.trim(),message:e.message.value.trim(),agreed:e.agreed.checked})})).json();if(!a.success)throw new Error(a.error);t.className="msg ok",t.textContent="신청이 접수되었습니다. 곧 연락드리겠습니다.",e.reset()}catch(s){t.className="msg err",t.textContent=s.message||"전송에 실패했습니다."}});
